reducedRules.rules:
@media (prefers-reduced-motion: reduce) {
  .studly-app *, .studly-app ::after, .studly-app ::before { animation: auto ease 0s 1 normal none running none !important; transition: none !important; scroll-behavior: auto !important; }
}

@media (prefers-reduced-motion: reduce) {
  .studly-app *, .studly-app ::after, .studly-app ::before { animation: auto ease 0s 1 normal none running none !important; transition: none !important; scroll-behavior: auto !important; }
  .studly-app .favorite-btn:hover, .studly-app .service-card:hover, .studly-app :is(.publish-btn, .search-submit, .detail-btn, .category-chip):active { transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .studly-app dialog[open] { animation: auto ease 0s 1 normal none running none; }
  .studly-app *, .studly-app ::after, .studly-app ::before { animation: auto ease 0s 1 normal none running none !important; transition: none !important; scroll-behavior: auto !important; }
}
